using System.Reflection;
using HPD.Agent.Authority;

namespace HPD.Agent.LiveAudio.Contracts.Tests.Authority;

public sealed class GraphParticipantReservationFoldV2Tests
{
    [Fact]
    public void Api_and_member_inventory_is_exact()
    {var t=typeof(GraphParticipantReservationFoldV2);Assert.Equal(["Apply","Complete","Create","Elect","Query"],t.GetMethods(BindingFlags.Instance|BindingFlags.Static|BindingFlags.NonPublic|BindingFlags.DeclaredOnly).Where(x=>x.IsAssembly).Select(x=>x.Name).Order().ToArray());Assert.Equal(15,t.GetNestedTypes(BindingFlags.NonPublic).Count(x=>!x.Name.StartsWith("<",StringComparison.Ordinal)));}

    [Fact]
    public void V2_empty_command_applied_and_rejected_histories_are_closed()
    {var s=Session();var empty=GraphParticipantReservationFoldV2.Create(s);empty.Complete();Assert.IsType<GraphParticipantReservationFoldV2.NotFound>(empty.Query(Op(1)));var command=Command(s,Op(2),1);var fold=GraphParticipantReservationFoldV2.Create(s);Assert.IsType<GraphParticipantReservationFoldV2.Accepted>(fold.Apply(command));fold.Complete();Assert.IsType<GraphParticipantReservationFoldV2.CommandOnly>(fold.Query(Op(2)));Assert.IsType<GraphParticipantReservationFoldV2.Leader>(fold.Elect(Op(2)));}

    [Fact]
    public void V1_applied_command_only_rejected_and_same_operation_follow_exact_law()
    {var s=Session();var fold=GraphParticipantReservationFoldV2.Create(s);Assert.IsType<GraphParticipantReservationFoldV2.Accepted>(fold.Apply(V1Command(s,Op(3),1)));Assert.Throws<InvalidOperationException>(()=>fold.Complete());var same=GraphParticipantReservationFoldV2.Create(s);same.Apply(V1Command(s,Op(4),1));Assert.IsType<GraphParticipantReservationFoldV2.InvalidHistory>(same.Apply(Command(s,Op(4),2)));}

    [Fact]
    public void Fact_join_and_predecessor_mutations_fail_closed()
    {var s=Session();var c=Command(s,Op(5),1);var fold=GraphParticipantReservationFoldV2.Create(s);fold.Apply(c);var bad=Fact(s,Op(5),c.Position,new JournalPositionV1(s,99),2,"reservation-predecessor-conflict",2);Assert.IsType<GraphParticipantReservationFoldV2.InvalidHistory>(fold.Apply(bad));var leader=Command(s,Op(20),1);var follower=Command(s,Op(21),2);var followerApplied=GraphParticipantReservationFoldV2.Create(s);followerApplied.Apply(leader);followerApplied.Apply(follower);Assert.IsType<GraphParticipantReservationFoldV2.InvalidHistory>(followerApplied.Apply(Fact(s,Op(21),follower.Position,null,1,"",3)));var followerCollision=GraphParticipantReservationFoldV2.Create(s);followerCollision.Apply(leader);followerCollision.Apply(follower);Assert.IsType<GraphParticipantReservationFoldV2.InvalidHistory>(followerCollision.Apply(Fact(s,Op(21),follower.Position,null,2,"participant-id-collision",3)));var sole=GraphParticipantReservationFoldV2.Create(s);sole.Apply(leader);Assert.IsType<GraphParticipantReservationFoldV2.InvalidHistory>(sole.Apply(Fact(s,Op(20),leader.Position,null,2,"participant-already-reserved",2)));var stale=GraphParticipantReservationFoldV2.Create(s);stale.Apply(leader);stale.Apply(Fact(s,Op(20),leader.Position,null,1,"",2));var late=Command(s,Op(22),3);stale.Apply(late);Assert.IsType<GraphParticipantReservationFoldV2.InvalidHistory>(stale.Apply(Fact(s,Op(22),late.Position,null,2,"participant-already-reserved",4)));var join0=GraphParticipantReservationFoldV2.Create(s);join0.Apply(c);var mutation0=Fact(s,Op(5),c.Position,null,1,"",2,"graph-generation");var invalid0=Assert.IsType<GraphParticipantReservationFoldV2.InvalidHistory>(join0.Apply(mutation0));Assert.Equal("command-fact-join-invalid",invalid0.SafeCode.ToString());var join1=GraphParticipantReservationFoldV2.Create(s);join1.Apply(c);var mutation1=Fact(s,Op(5),c.Position,null,1,"",2,"runtime-generation");var invalid1=Assert.IsType<GraphParticipantReservationFoldV2.InvalidHistory>(join1.Apply(mutation1));Assert.Equal("command-fact-join-invalid",invalid1.SafeCode.ToString());var join2=GraphParticipantReservationFoldV2.Create(s);join2.Apply(c);var mutation2=Fact(s,Op(5),c.Position,null,1,"",2,"plan-fingerprint");var invalid2=Assert.IsType<GraphParticipantReservationFoldV2.InvalidHistory>(join2.Apply(mutation2));Assert.Equal("command-fact-join-invalid",invalid2.SafeCode.ToString());var join3=GraphParticipantReservationFoldV2.Create(s);join3.Apply(c);var mutation3=Fact(s,Op(5),c.Position,null,1,"",2,"carrier-fingerprint");var invalid3=Assert.IsType<GraphParticipantReservationFoldV2.InvalidHistory>(join3.Apply(mutation3));Assert.Equal("command-fact-join-invalid",invalid3.SafeCode.ToString());var join4=GraphParticipantReservationFoldV2.Create(s);join4.Apply(c);var mutation4=Fact(s,Op(5),c.Position,null,1,"",2,"factory");var invalid4=Assert.IsType<GraphParticipantReservationFoldV2.InvalidHistory>(join4.Apply(mutation4));Assert.Equal("singleton-duplicate",invalid4.SafeCode.ToString());var join5=GraphParticipantReservationFoldV2.Create(s);join5.Apply(c);var mutation5=Fact(s,Op(5),c.Position,null,1,"",2,"node-list");var invalid5=Assert.IsType<GraphParticipantReservationFoldV2.InvalidHistory>(join5.Apply(mutation5));Assert.Equal("singleton-duplicate",invalid5.SafeCode.ToString());var join6=GraphParticipantReservationFoldV2.Create(s);join6.Apply(c);var mutation6=Fact(s,Op(5),c.Position,null,1,"",2,"correlation");var invalid6=Assert.IsType<GraphParticipantReservationFoldV2.InvalidHistory>(join6.Apply(mutation6));Assert.Equal("command-fact-join-invalid",invalid6.SafeCode.ToString());var join7=GraphParticipantReservationFoldV2.Create(s);join7.Apply(c);var mutation7=Fact(s,Op(5),c.Position,null,1,"",2,"expected-authority");var invalid7=Assert.IsType<GraphParticipantReservationFoldV2.InvalidHistory>(join7.Apply(mutation7));Assert.Equal("command-fact-join-invalid",invalid7.SafeCode.ToString());var join8=GraphParticipantReservationFoldV2.Create(s);join8.Apply(c);var mutation8=Fact(s,Op(5),c.Position,null,1,"",2,"body-observed");var invalid8=Assert.IsType<GraphParticipantReservationFoldV2.InvalidHistory>(join8.Apply(mutation8));Assert.Equal("command-fact-join-invalid",invalid8.SafeCode.ToString());var join9=GraphParticipantReservationFoldV2.Create(s);join9.Apply(c);var mutation9=Fact(s,Op(5),c.Position,null,1,"",2,"envelope-observed");var invalid9=Assert.IsType<GraphParticipantReservationFoldV2.InvalidHistory>(join9.Apply(mutation9));Assert.Equal("command-fact-join-invalid",invalid9.SafeCode.ToString());var join10=GraphParticipantReservationFoldV2.Create(s);join10.Apply(c);var mutation10=Fact(s,Op(5),c.Position,null,1,"",2,"operation");var invalid10=Assert.IsType<GraphParticipantReservationFoldV2.InvalidHistory>(join10.Apply(mutation10));Assert.Equal("command-fact-join-invalid",invalid10.SafeCode.ToString());var join11=GraphParticipantReservationFoldV2.Create(s);join11.Apply(c);var mutation11=Fact(s,Op(5),c.Position,null,1,"",2,"command-position");var invalid11=Assert.IsType<GraphParticipantReservationFoldV2.InvalidHistory>(join11.Apply(mutation11));Assert.Equal("command-fact-join-invalid",invalid11.SafeCode.ToString());var join12=GraphParticipantReservationFoldV2.Create(s);join12.Apply(c);var mutation12=Fact(s,Op(5),c.Position,null,1,"",2,"outer-session");var invalid12=Assert.IsType<GraphParticipantReservationFoldV2.InvalidHistory>(join12.Apply(mutation12));Assert.Equal("session-mismatch",invalid12.SafeCode.ToString());}

    [Fact]
    public void Election_is_position_stable_and_never_promotes_follower()
    {var s=Session();var a=Command(s,Op(6),1);var b=Command(s,Op(7),2);var fold=GraphParticipantReservationFoldV2.Create(s);fold.Apply(a);fold.Apply(b);fold.Complete();Assert.IsType<GraphParticipantReservationFoldV2.Leader>(fold.Elect(Op(6)));var follower=Assert.IsType<GraphParticipantReservationFoldV2.Follower>(fold.Elect(Op(7)));Assert.Equal(a.Position,follower.LeaderCommand.Position);var resolved=GraphParticipantReservationFoldV2.Create(s);resolved.Apply(a);resolved.Apply(b);Assert.IsType<GraphParticipantReservationFoldV2.Accepted>(resolved.Apply(Fact(s,Op(6),a.Position,null,2,"participant-id-collision",3)));resolved.Complete();Assert.IsType<GraphParticipantReservationFoldV2.Leader>(resolved.Elect(Op(7)));}

    [Fact]
    public void Bounds_duplicates_and_cross_version_fact_ids_fail_closed()
    {var s=Session();var c=Command(s,Op(8),1);var fold=GraphParticipantReservationFoldV2.Create(s);fold.Apply(c);Assert.IsType<GraphParticipantReservationFoldV2.InvalidHistory>(fold.Apply(c));Assert.NotEqual(GraphParticipantBindingFactIdsV1.ReservationCommand(s,Op(8)),GraphParticipantReservationFactIdsV2.ReservationCommand(s,Op(8)));var v2ThenV1=GraphParticipantReservationFoldV2.Create(s);v2ThenV1.Apply(c);v2ThenV1.Apply(Fact(s,Op(8),c.Position,null,1,"",2));var legacy=V1Command(s,Op(9),3);Assert.IsType<GraphParticipantReservationFoldV2.InvalidHistory>(v2ThenV1.Apply(V1Fact(s,Op(9),legacy.Position,4)));var v1ThenV2=GraphParticipantReservationFoldV2.Create(s);var legacyFirst=V1Command(s,Op(10),1);v1ThenV2.Apply(legacyFirst);v1ThenV2.Apply(V1Fact(s,Op(10),legacyFirst.Position,2));var modern=Command(s,Op(11),3);v1ThenV2.Apply(modern);Assert.IsType<GraphParticipantReservationFoldV2.InvalidHistory>(v1ThenV2.Apply(Fact(s,Op(11),modern.Position,null,1,"",4)));}

    private static AuthorityFactEnvelopeV1 Command(SessionAuthorityStampV1 s,OperationId op,long sequence)
    {var graph=GraphGenerationId.FromValue(Id(20));var authority=ExpectedAuthorityVectorV1.Create(s,[new AuthorityAxisValueV1.Graph(graph)]);var body=new GraphParticipantReservationCommandBodyV2(op,null,s.RuntimeGenerationId,graph,Hash256.Compute([1]),Hash256.Compute([2]),new("factory"),[new("a"),new("b")],Stamp());var payload=GraphParticipantReservationCodecsV2.Encode(new GraphParticipantReservationCommandV2(s,authority,GraphParticipantReservationCodecsV2.Encode(body)));return Envelope(GraphParticipantReservationFactIdsV2.ReservationCommand(s,op),new(s,sequence),GraphParticipantReservationPayloadRegistrationsV2.ReservationCommand,payload,op);}
    private static AuthorityFactEnvelopeV1 Fact(SessionAuthorityStampV1 s,OperationId op,JournalPositionV1 command,JournalPositionV1? predecessor,ushort outcome,string code,long sequence,string mutation="")
    {var outerSession=mutation=="outer-session"?new SessionAuthorityStampV1(RuntimeGenerationId.FromValue(Id(97)),LiveSessionId.FromValue(Id(98))):s;var graph=GraphGenerationId.FromValue(Id((byte)(mutation=="graph-generation"?21:20)));var authorityGraph=GraphGenerationId.FromValue(Id((byte)(mutation=="expected-authority"?22:20)));var authority=ExpectedAuthorityVectorV1.Create(outerSession,[new AuthorityAxisValueV1.Graph(authorityGraph)]);var factory=mutation=="factory"?new BoundedAscii("changed"):new BoundedAscii("factory");var nodes=mutation=="node-list"?[new BoundedAscii("changed")]:new BoundedAscii[]{new("a"),new("b")};var reservation=outcome==1?new GraphParticipantReservationV1(ParticipantId.FromValue(Id(40)),factory,nodes):null;var runtime=mutation=="runtime-generation"?RuntimeGenerationId.FromValue(Id(99)):s.RuntimeGenerationId;var plan=Hash256.Compute(mutation=="plan-fingerprint"?new byte[]{9}:new byte[]{1});var carrier=Hash256.Compute(mutation=="carrier-fingerprint"?new byte[]{9}:new byte[]{2});var observed=mutation=="body-observed"?new MonotonicStampV1(ClockDomainId.FromValue(Id(12)),BootId.FromValue(Id(13)),2):Stamp();var factOperation=mutation=="operation"?Op(99):op;var bodyCommand=mutation=="command-position"?new JournalPositionV1(s,99):command;var body=new GraphParticipantReservationFactBodyV2(factOperation,bodyCommand,predecessor,outcome,runtime,graph,plan,carrier,reservation,string.IsNullOrEmpty(code)?null:new(code),observed);var payload=GraphParticipantReservationCodecsV2.Encode(new GraphParticipantReservationFactV2(outerSession,authority,GraphParticipantReservationCodecsV2.Encode(body)));var registration=GraphParticipantReservationPayloadRegistrationsV2.ReservationFact;var correlation=mutation=="correlation"?new CorrelationEnvelopeV1(TenantId.FromValue(Id(31)),operationId:op):new CorrelationEnvelopeV1(TenantId.FromValue(Id(30)),operationId:op);var envelopeObserved=mutation=="envelope-observed"?new UtcInstant(1):default;return new(GraphParticipantReservationFactIdsV2.ReservationFact(command),new(s,sequence),null,OwnerSliceId.S1,registration.Schema,payload,AuthorityPayloadHashV1.Compute(registration.SchemaToken,registration.Schema,payload),correlation,envelopeObserved,default,new IntegrityEnvelopeV1(1,1,Hash256.Compute([9]),[]));}
    private static AuthorityFactEnvelopeV1 V1Command(SessionAuthorityStampV1 s,OperationId op,long sequence)
    {var body=new GraphParticipantReservationCommandBodyV1(op,null,s.RuntimeGenerationId,Hash256.Compute([1]),Hash256.Compute([2]),Hash256.Compute([3]),new("factory"),[new("a")],Stamp());var authority=ExpectedAuthorityVectorV1.Create(s,[]);var payload=GraphParticipantBindingCodecsV1.Encode(new GraphParticipantReservationCommandV1(s,authority,GraphParticipantBindingCodecsV1.Encode(body)));return Envelope(GraphParticipantBindingFactIdsV1.ReservationCommand(s,op),new(s,sequence),GraphParticipantBindingPayloadRegistrationsV1.ReservationCommand,payload,op);}
    private static AuthorityFactEnvelopeV1 V1Fact(SessionAuthorityStampV1 s,OperationId op,JournalPositionV1 command,long sequence)
    {var authority=ExpectedAuthorityVectorV1.Create(s,[]);var reservation=new GraphParticipantReservationV1(ParticipantId.FromValue(Id(41)),new("factory"),[new("a")]);var body=new GraphParticipantReservationFactBodyV1(op,command,null,1,s.RuntimeGenerationId,Hash256.Compute([1]),Hash256.Compute([2]),Hash256.Compute([3]),reservation,null,Stamp());var payload=GraphParticipantBindingCodecsV1.Encode(new GraphParticipantReservationFactV1(s,authority,GraphParticipantBindingCodecsV1.Encode(body)));return Envelope(GraphParticipantBindingFactIdsV1.ReservationFact(command),new(s,sequence),GraphParticipantBindingPayloadRegistrationsV1.ReservationFact,payload,op);}
    private static AuthorityFactEnvelopeV1 Envelope(JournalFactId id,JournalPositionV1 p,AuthorityPayloadRegistrationV1 r,byte[] payload,OperationId op)=>new(id,p,null,OwnerSliceId.S1,r.Schema,payload,AuthorityPayloadHashV1.Compute(r.SchemaToken,r.Schema,payload),new CorrelationEnvelopeV1(TenantId.FromValue(Id(30)),operationId:op),default,default,new IntegrityEnvelopeV1(1,1,Hash256.Compute([9]),[]));
    private static SessionAuthorityStampV1 Session()=>new(RuntimeGenerationId.FromValue(Id(10)),LiveSessionId.FromValue(Id(11)));
    private static OperationId Op(byte x)=>OperationId.FromValue(Id(x));private static MonotonicStampV1 Stamp()=>new(ClockDomainId.FromValue(Id(12)),BootId.FromValue(Id(13)),1);
    private static StableId128 Id(byte x){var b=new byte[16];b[^1]=x;return StableId128.FromBytes(b);}
}
